window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4cbd33853b7c6ea9"]={"versions": [{"id": "FIG-4cbd33853b7c6ea9", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Architektur- und Kontrollflussdiagramm im Kontext der AUTOSAR Classic Platform (Timing Extensions). Das Diagramm veranschaulicht die Schichtenarchitektur aus Basic Software (BSW), Runtime Environment (RTE), Complex Device Driver (CDD) und Application/Actuator-Ebene zur Modellierung von zeitlichen Abhängigkeiten und Auslösepfaden für Timing Requirement 4.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind drei Software-Komponenten bzw. -Module sowie die vermittelnde Schicht:</p>\n<ul class=\"fig-list\"><li><strong>Camshaft</strong> (<code>Basic Software Module</code>): Beinhaltet eine <code>BSWME ISR</code> (BSW Module Entity als Interrupt Service Routine).\n</li><li><strong>Runtime Environment</strong> (RTE): Zentrale Vermittlungsschicht zwischen BSW/Treibern und SW-Cs.\n</li><li><strong>Ignition Actuator</strong> (<code>Actuator Software Component</code> mit Aktor-Symbol oben rechts): Enthält eine <code>RE</code> (Runnable Entity) sowie zwei Ports am unteren Komponentenrand: einen Empfangsport (Pfeil nach oben im Quadrat) mit Verbindung in die RTE und einen Sendeport (Pfeil nach unten im Quadrat).\n</li><li><strong>Ignition</strong> (<code>Complex Device Driver</code>): Enthält eine <code>RE</code> (Runnable Entity) und einen Empfangsport am oberen Komponentenrand (Pfeil nach unten im Quadrat).\n</li><li><strong>Legende</strong>: Definiert <code>RE</code> als <em>Runnable Entity</em>, <code>BSWME</code> als <em>BSW Module Entity (ISR)</em> und <code>ISR</code> als <em>Interrupt Service Routine</em>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei primäre Interaktions- und Kontrollflüsse dar:</p>\n<ol class=\"fig-list\"><li><strong>Asynchroner Aktivierungspfad / Kontrollfluss</strong>: Ausgehend von der Interrupt Service Routine <code>BSWME ISR</code> des <code>Camshaft</code>-Moduls führt eine gestrichelte Pfeillinie mit der Beschriftung <code>Activate</code> über die Grenzen der BSW-Schicht hinweg direkt zur Runnable Entity <code>RE</code> der Komponente <code>Ignition Actuator</code>.\n</li><li><strong>Daten- bzw. Aufruffluss über RTE</strong>: Vom Sendeport der Komponente <code>Ignition Actuator</code> verläuft eine durchgehende Verbindungslinie durch die RTE hindurch zum Empfangsport des Complex Device Drivers <code>Ignition</code>. Zudem führt eine Verbindung vom Empfangsport des <code>Ignition Actuator</code> in die RTE (dort gestrichelt abknickend angedeutet).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für die Spezifikation von AUTOSAR Timing Descriptions (AUTOSAR_TPS_TimingExtensions). Das Diagramm illustriert ein Ausführungs- und Timing-Szenario, bei dem ein hardwarenahes Ereignis (ISR in einem BSW-Modul) eine Aktivierung einer Anwendungs-Runnable (Actuator SW-C) triggert, deren Ausgabe wiederum über RTE-Ports an einen CDD weitergeleitet wird. Entwickler müssen bei der Timing-Modellierung (z. B. <code>TimingDescriptionEventChain</code>, <code>LatencyTimingConstraint</code>) berücksichtigen, dass Aktivierungspfade zwischen BSW-Entities und SW-C Runnables sowie Port-basierte Kommunikation über die RTE getrennte Segmente der Ereigniskette bilden.</p>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-c2e64e18bbd5b921", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Strukturelles Architektur- und Kontrollflussdiagramm im Kontext der AUTOSAR Classic Platform (Timing Extensions). Das Diagramm veranschaulicht die Schichtenarchitektur aus Basic Software (BSW), Runtime Environment (RTE), Complex Device Driver (CDD) und Application/Actuator-Ebene zur Modellierung von zeitlichen Abhängigkeiten und Auslösepfaden für Timing Requirement 4.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Dargestellt sind drei Software-Komponenten bzw. -Module sowie die vermittelnde Schicht:</p>\n<ul class=\"fig-list\"><li><strong>Camshaft</strong> (<code>Basic Software Module</code>): Beinhaltet eine <code>BSWME ISR</code> (BSW Module Entity als Interrupt Service Routine).\n</li><li><strong>Runtime Environment</strong> (RTE): Zentrale Vermittlungsschicht zwischen BSW/Treibern und SW-Cs.\n</li><li><strong>Ignition Actuator</strong> (<code>Actuator Software Component</code> mit Aktor-Symbol oben rechts): Enthält eine <code>RE</code> (Runnable Entity) sowie zwei Ports am unteren Komponentenrand: einen Empfangsport (Pfeil nach oben im Quadrat) mit Verbindung in die RTE und einen Sendeport (Pfeil nach unten im Quadrat).\n</li><li><strong>Ignition</strong> (<code>Complex Device Driver</code>): Enthält eine <code>RE</code> (Runnable Entity) und einen Empfangsport am oberen Komponentenrand (Pfeil nach unten im Quadrat).\n</li><li><strong>Legende</strong>: Definiert <code>RE</code> als <em>Runnable Entity</em>, <code>BSWME</code> als <em>BSW Module Entity (ISR)</em> und <code>ISR</code> als <em>Interrupt Service Routine</em>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt zwei primäre Interaktions- und Kontrollflüsse dar:</p>\n<ol class=\"fig-list\"><li><strong>Asynchroner Aktivierungspfad / Kontrollfluss</strong>: Ausgehend von der Interrupt Service Routine <code>BSWME ISR</code> des <code>Camshaft</code>-Moduls führt eine gestrichelte Pfeillinie mit der Beschriftung <code>Activate</code> über die Grenzen der BSW-Schicht hinweg direkt zur Runnable Entity <code>RE</code> der Komponente <code>Ignition Actuator</code>.\n</li><li><strong>Daten- bzw. Aufruffluss über RTE</strong>: Vom Sendeport der Komponente <code>Ignition Actuator</code> verläuft eine durchgehende Verbindungslinie durch die RTE hindurch zum Empfangsport des Complex Device Drivers <code>Ignition</code>. Zudem führt eine Verbindung vom Empfangsport des <code>Ignition Actuator</code> in die RTE (dort gestrichelt abknickend angedeutet).\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Relevant für die Spezifikation von AUTOSAR Timing Descriptions (AUTOSAR_TPS_TimingExtensions). Das Diagramm illustriert ein Ausführungs- und Timing-Szenario, bei dem ein hardwarenahes Ereignis (ISR in einem BSW-Modul) eine Aktivierung einer Anwendungs-Runnable (Actuator SW-C) triggert, deren Ausgabe wiederum über RTE-Ports an einen CDD weitergeleitet wird. Entwickler müssen bei der Timing-Modellierung (z. B. <code>TimingDescriptionEventChain</code>, <code>LatencyTimingConstraint</code>) berücksichtigen, dass Aktivierungspfade zwischen BSW-Entities und SW-C Runnables sowie Port-basierte Kommunikation über die RTE getrennte Segmente der Ereigniskette bilden.</p>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-4cbd33853b7c6ea9", "to": "FIG-c2e64e18bbd5b921", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c2e64e18bbd5b921", "to": "FIG-4cbd33853b7c6ea9", "fr": "R20-11", "tr": "R22-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
